const DICC = { es: ES, en: EN, ca: CA, gl: GL };
let actual = "es";

/** Idioma activo: guardado, o el del navegador si es uno de los soportados. */
export function idioma() { return actual; }

export function detectarIdioma() {
  try {
    const g = localStorage.getItem(CLAVE);
    if (g && DICC[g]) return g;
  } catch {}
  const nav = (navigator.language || "es").slice(0, 2).toLowerCase();
  return DICC[nav] ? nav : "es";
}

/** Traduce una clave con sustituciones {n}. Si no existe en el idioma, vuelve al español. */
export function t(clave, vars) {
  let s = DICC[actual]?.[clave] ?? ES[clave] ?? clave;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}

/** Aplica el idioma a los elementos con data-i18n / data-i18n-ph / data-i18n-title / data-i18n-aria. */
export function aplicarIdioma(lang) {
  actual = DICC[lang] ? lang : "es";
  try { localStorage.setItem(CLAVE, actual); } catch {}
  document.documentElement.lang = actual;
  for (const el of document.querySelectorAll("[data-i18n]")) {
    const k = el.dataset.i18n;
    if (el.dataset.i18nHtml != null) { el.innerHTML = t(k); continue; }
    const svg = el.querySelector(":scope > svg");  // conservar el icono del botón
    el.textContent = t(k);
    if (svg) el.prepend(svg);
  }
  for (const el of document.querySelectorAll("[data-i18n-ph]")) el.placeholder = t(el.dataset.i18nPh);
  for (const el of document.querySelectorAll("[data-i18n-title]")) el.title = t(el.dataset.i18nTitle);
  for (const el of document.querySelectorAll("[data-i18n-aria]")) el.setAttribute("aria-label", t(el.dataset.i18nAria));
  document.title = `${t("meta.titulo")} · ${t("meta.subtitulo")}`;
  const aviso = document.getElementById("aviso-idioma");
  if (aviso) { aviso.hidden = actual === "es"; aviso.textContent = t("aviso.idioma"); }
  document.dispatchEvent(new CustomEvent("idioma", { detail: actual }));
}
